		t.Fatal(err)
	}
	if r := runCLIWith(t, []string{"reconcile", "-l", corrupt}, `{"entries":[]}`); r.code != 1 ||
		decodeOut(t, r.err)["error"].(map[string]any)["kind"] != "corrupt_ledger" {
