		[]Intent{{ID: "x"}, {ID: "missing"}},
		[]Settlement{{Intent: "x", Status: "settled"}},
	); len(gaps) != 1 || gaps[0] != "missing" {
		t.Fatalf("legacy reconcile gaps=%v", gaps)
	}
}

